insert into public.faq_items(question,answer,category,is_published,sort_order) select * from(values
('Como funciona o primeiro atendimento?','A equipe recebe um resumo e informa os próximos passos.','Atendimento',true,1),('O escritório realiza atendimento online?','Sim, conforme disponibilidade.','Atendimento online',true,2),('Quais informações devo enviar inicialmente?','Somente dados mínimos e resumo.','Privacidade',true,3),('Preciso enviar documentos no primeiro contato?','Não. Aguarde orientação.','Documentos',true,4),('O envio cria relação advogado-cliente?','Não, depende de formalização.','Consulta',true,5),('Como os dados serão utilizados?','Para responder e organizar o atendimento.','Privacidade',true,6),('Em quais áreas o escritório atua?','Trabalhista, Família, Previdenciário e Empresarial.','Áreas',true,7),('Como saber se podem analisar meu caso?','Envie um resumo pelos canais oficiais.','Consulta',true,8)) as v(question,answer,category,is_published,sort_order);
